INSERT INTO public.categories_productcategory VALUES (1, 'Vegetables', 'Fresh, farm-picked vegetables delivered with quality and freshness you can trust. Choose from a wide range of leafy greens, root vegetables, gourds, and seasonal produce for your everyday cooking needs.', 'vegetables', 'categories/vegetables.jpeg', 'active', '2026-07-29 08:39:53.774533+00', '2026-08-04 12:06:37.607461+00', NULL);
