INSERT INTO public.products_product VALUES (13, 'Beans', 'Mint Grow Farm Beans are carefully cultivated and harvested to ensure freshness, tenderness, and excellent quality. Selected for their vibrant appearance and crisp texture, our beans are suitable for a wide variety of everyday dishes.
INSERT INTO public.products_product VALUES (17, 'Mint Leaves', 'Our fresh Mint Leaves are handpicked from trusted farms to ensure exceptional freshness, aroma, and quality. Their cool, refreshing flavor makes them ideal for preparing chutneys, mint rice, salads, curries, herbal teas, juices, and refreshing drinks like mojitos and lemon mint coolers. Rich in vitamins, antioxidants, and natural goodness, mint adds both taste and freshness to your everyday meals. Enjoy farm-fresh Mint Leaves delivered straight to your doorstep.', 'Fresh, aromatic Mint Leaves with a refreshing flavor, perfect for chutneys, beverages, salads, curries, and garnishing.', 'products/mint-leaves-img.jpeg', 'mint-leaves', true, 'MG005', 'active', '2026-08-04 12:15:49.092934+00', '2026-08-14 11:04:27.324445+00', 2);
INSERT INTO public.products_product VALUES (18, 'Coriander Leaves', 'Our fresh Coriander Leaves are carefully handpicked from trusted farms to ensure maximum freshness, aroma, and quality. Their vibrant flavor enhances curries, dals, soups, salads, chutneys, and rice dishes, making them an essential ingredient in every kitchen. Rich in vitamins, antioxidants, and natural nutrients, coriander leaves add both taste and freshness to your meals. Enjoy farm-fresh Coriander Leaves delivered straight to your doorstep.', 'Fresh, fragrant Coriander Leaves, perfect for garnishing, chutneys, curries, soups, and a variety of everyday dishes.', 'products/coriander-leaves-img.jpeg', 'coriander-leaves', true, 'MG006', 'active', '2026-08-04 12:19:10.930399+00', '2026-08-14 11:05:05.113831+00', 2);
INSERT INTO public.products_product VALUES (23, 'Bajji Chilli', 'Our fresh Bajji Chillies are carefully selected for their quality, size, and freshness. Known for their mild heat and thick flesh, they are ideal for preparing traditional South Indian chilli bajji. Simply coat them in seasoned gram flour batter and fry for a crispy, tasty snack. They can also be used in various Indian recipes for adding flavor and texture.', 'Fresh Bajji Chillies with a mild flavor, perfect for making crispy and delicious chilli bajji.', 'products/bujji-chilly-img.jpeg', 'bajji-chilli', false, 'MG0011', 'active', '2026-08-20 07:14:10.820331+00', '2026-08-20 07:14:10.820342+00', 1);
INSERT INTO public.products_product VALUES (16, 'Bitter Guard', 'Our fresh Bitter Gourd is carefully sourced from trusted farms to ensure superior quality and freshness. Known for its unique taste and numerous health benefits, it is widely used in curries, stir-fries, stuffed dishes, chips, and juices. Rich in dietary fiber, vitamins, and antioxidants, Bitter Gourd is a nutritious choice for a balanced diet. Enjoy farm-fresh Bitter Gourd delivered straight to your doorstep for healthy and delicious home cooking.', 'Fresh, tender Bitter Gourd with a distinctive flavor, perfect for stir-fries, curries, fries, and traditional healthy recipes.', 'products/bitter-guard-img.jpeg', 'bitter-guard', true, 'MG004', 'active', '2026-08-04 12:13:34.842837+00', '2026-08-14 11:02:46.265594+00', 1);
INSERT INTO public.products_product VALUES (15, 'Brinjal Long Green', 'Our Long Green Brinjal is carefully selected from fresh farm harvests to ensure excellent quality, freshness, and taste. With its tender flesh and mild flavor, it is ideal for preparing curries, sambar, stir-fries, stuffed brinjal, roasted dishes, and other everyday recipes. Rich in dietary fiber, vitamins, and antioxidants, this versatile vegetable is a healthy addition to your meals. Enjoy fresh, farm-picked Long Green Brinjal delivered to your doorstep.', 'Fresh, tender Long Green Brinjal with a mild flavor and soft texture, perfect for curries, stir-fries, stuffed dishes, and traditional recipes.', 'products/brinjal-long-green-img.jpeg', 'brinjal-long-green', false, 'MG003', 'active', '2026-08-04 12:12:28.998394+00', '2026-08-14 11:03:04.419622+00', 1);
INSERT INTO public.products_product VALUES (14, 'Brinjal Vari', 'Mint Grow Farm Brinjal Vari is cultivated with care and harvested at the right stage to maintain freshness, tenderness, and natural flavor. Each brinjal is carefully selected to provide consistent quality and a smooth texture suitable for everyday cooking.
INSERT INTO public.products_product VALUES (20, 'Cauliflower', 'Fresh Cauliflower is a versatile and nutritious vegetable with compact, tender florets and a mild, slightly sweet flavor. It is a great addition to a variety of dishes, including curries, stir-fries, soups, roasted preparations, and salads. Easy to clean and cook, cauliflower is a delicious choice for healthy everyday meals.', 'Fresh and nutritious cauliflower with crisp florets and a mild, delicate flavor. Perfect for curries, stir-fries, soups, and everyday cooking.', 'products/cauliflower-img.jpeg', 'cauliflower', false, 'MG008', 'active', '2026-08-20 06:55:38.206235+00', '2026-08-20 06:55:38.206248+00', 1);
INSERT INTO public.products_product VALUES (21, 'Cucumber Green', '', '', 'products/cucumber-img.jpeg', 'cucumber-green', false, 'MG009', 'active', '2026-08-20 07:04:15.266419+00', '2026-08-20 07:04:15.266431+00', 1);
INSERT INTO public.products_product VALUES (22, 'Arai Keerai', 'Arai Keerai is a popular leafy green vegetable known for its fresh taste and nutritional value. It is commonly used in South Indian cooking to prepare kootu, masiyal, poriyal, soups, and other healthy dishes. Carefully selected for freshness, Arai Keerai is a delicious addition to your daily meals and a great choice for a balanced diet.', 'Fresh and nutritious Arai Keerai, perfect for preparing healthy South Indian dishes, soups, curries, and stir-fries.', 'products/araikeerai-img.jpeg', 'arai-keerai', false, 'MG0010', 'active', '2026-08-20 07:11:01.931301+00', '2026-08-20 07:11:01.931321+00', 2);
INSERT INTO public.products_product VALUES (24, 'Beetroot', 'Our fresh beetroot is carefully selected for its rich color, natural sweetness, and quality. It can be used in salads, juices, soups, curries, poriyal, and a variety of healthy recipes. A versatile vegetable that adds natural flavor, color, and nutrition to your everyday meals.', 'Fresh and naturally sweet beetroot, perfect for salads, juices, curries, and healthy meals.', 'products/beetroot-img.jpeg', 'beetroot', false, 'MG0012', 'active', '2026-08-20 07:17:03.222194+00', '2026-08-20 07:17:03.222214+00', 1);
INSERT INTO public.products_product VALUES (25, 'Bottle Gourd', 'Our fresh bottle gourd is carefully selected for its tender texture and natural freshness. It is a versatile vegetable commonly used in curries, kootu, poriyal, soups, juices, and various Indian dishes. With its mild taste and soft texture, bottle gourd is a great addition to healthy and everyday meals.', 'Fresh and tender bottle gourd, perfect for curries, kootu, soups, and other healthy dishes.', 'products/bottle-guard-img.jpeg', 'bottle-gourd', false, 'MG0013', 'active', '2026-08-20 07:18:23.284522+00', '2026-08-20 07:18:23.284533+00', 1);
INSERT INTO public.products_product VALUES (26, 'Capsicum Green', 'Our fresh green capsicum is carefully selected for its crisp texture, vibrant colour, and natural flavour. It is a versatile vegetable that can be used in curries, stir-fries, salads, noodles, fried rice, pizzas, sandwiches, and many other recipes. A fresh and delicious addition to your everyday meals.', 'Fresh and crisp green capsicum, perfect for curries, stir-fries, salads, pizzas, and a variety of dishes.', 'products/capsicum-green-img.jpeg', 'capsicum-green', false, 'MG0014', 'active', '2026-08-20 07:19:49.372725+00', '2026-08-20 07:19:49.372738+00', 1);
INSERT INTO public.products_product VALUES (27, 'Capsicum Red', 'Our fresh red capsicum is carefully selected for its bright colour, crisp texture, and naturally sweet taste. It is a versatile vegetable that can be used in salads, stir-fries, curries, noodles, fried rice, pizzas, sandwiches, and many other recipes. A colourful and delicious addition to your everyday meals.', 'Fresh and vibrant red capsicum with a crisp texture and naturally sweet flavour, perfect for salads, stir-fries, pizzas, and various dishes.', 'products/capsicum-red-img.jpeg', 'capsicum-red', false, 'MG0015', 'active', '2026-08-20 07:21:03.814519+00', '2026-08-20 07:21:03.814531+00', 1);
INSERT INTO public.products_product VALUES (28, 'Capsicum Yellow', 'Our fresh yellow capsicum is carefully selected for its vibrant colour, crisp texture, and naturally sweet taste. It is a versatile vegetable that can be used in salads, stir-fries, curries, noodles, fried rice, pizzas, sandwiches, and many other recipes. A colourful and delicious addition to your everyday meals.', 'Fresh and colourful yellow capsicum with a crisp texture and naturally sweet flavour, perfect for salads, stir-fries, pizzas, and various dishes.', 'products/capsicum-yellow-img.jpeg', 'capsicum-yellow', false, 'MG0016', 'active', '2026-08-20 07:22:36.20145+00', '2026-08-20 07:22:36.201461+00', 1);
INSERT INTO public.products_product VALUES (29, 'Carrot', 'Our fresh carrots are carefully selected for their bright colour, crisp texture, and natural sweetness. They are versatile vegetables that can be used in salads, juices, soups, curries, stir-fries, fried rice, and many other dishes. A fresh and delicious addition to your everyday meals.', 'Fresh and crunchy carrots with a naturally sweet taste, perfect for salads, juices, soups, curries, and healthy meals.', '', 'carrot', false, 'MG0017', 'active', '2026-08-20 07:24:52.296015+00', '2026-08-20 07:24:52.296027+00', 1);
INSERT INTO public.products_product VALUES (30, 'Chilli Green', 'Our fresh green chillies are carefully selected for their quality, freshness, and natural spicy flavour. They are commonly used in curries, chutneys, stir-fries, pickles, sauces, and a variety of Indian dishes. A perfect ingredient for adding extra spice and flavour to your everyday cooking.', 'Fresh green chillies with a vibrant colour and spicy flavour, perfect for adding heat and taste to your favourite dishes.', 'products/green-chilly-img.jpeg', 'chilli-green', false, 'MG0018', 'active', '2026-08-20 07:26:56.957905+00', '2026-08-20 07:26:56.957916+00', 1);
INSERT INTO public.products_product VALUES (31, 'Chow Chow', 'Our fresh Chow Chow is carefully selected for its tender texture, mild flavour, and natural freshness. Also known as chayote, it is commonly used in South Indian dishes such as kootu, poriyal, sambar, curries, and soups. A versatile and delicious vegetable for your everyday meals.', 'Fresh and tender Chow Chow, perfect for curries, kootu, poriyal, soups, and a variety of healthy dishes.', 'products/chow-chow-img.jpeg', 'chow-chow', false, 'MG0019', 'active', '2026-08-20 07:29:45.078874+00', '2026-08-20 07:29:45.078887+00', 1);
INSERT INTO public.products_product VALUES (32, 'Curry Leaves', 'Our fresh curry leaves are carefully selected for their natural aroma, flavour, and freshness. They are commonly used in South Indian and Indian cooking for tempering curries, sambar, rasam, chutneys, rice dishes, and many other recipes. A must-have ingredient for adding authentic taste and aroma to your everyday meals.', 'Fresh and aromatic curry leaves, perfect for adding natural flavour and fragrance to a variety of Indian dishes.', 'products/curry-leaves-img.jpeg', 'curry-leaves', false, 'MG0020', 'active', '2026-08-20 07:32:21.031798+00', '2026-08-20 07:32:21.03181+00', 1);
INSERT INTO public.products_product VALUES (33, 'Dantu Leaves', 'Our fresh Dantu Leaves are carefully selected for their quality, tenderness, and natural freshness. They can be used to prepare a variety of traditional dishes, including poriyal, kootu, curries, and stir-fries. A flavourful and nutritious leafy vegetable, perfect for adding variety to your everyday meals.', 'Fresh and nutritious Dantu Leaves, perfect for preparing healthy curries, poriyal, kootu, and traditional Indian dishes.', 'products/dantu-leaves-img.jpeg', 'dantu-leaves', false, 'MG0021', 'active', '2026-08-20 07:35:44.910507+00', '2026-08-20 07:35:44.910519+00', 2);
INSERT INTO public.products_product VALUES (35, 'Drumstick', 'Our fresh drumsticks are carefully selected for their quality, tenderness, and natural flavour. They are commonly used in South Indian dishes such as sambar, curries, kootu, soups, and gravies. A versatile and flavourful vegetable that adds a delicious taste to your everyday meals.', 'Fresh and tender drumsticks, perfect for sambar, curries, soups, and a variety of traditional Indian dishes.', 'products/drumstick-img.jpeg', 'drumstick', false, 'MG0023', 'active', '2026-08-20 08:54:46.401502+00', '2026-08-20 08:54:46.401514+00', 1);
INSERT INTO public.products_product VALUES (34, 'Dill Leaves', 'Our fresh dill leaves are carefully selected for their natural aroma, delicate texture, and distinctive flavour. They can be used in curries, soups, salads, stir-fries, dals, and a variety of Indian dishes. A fresh and flavourful leafy ingredient that adds a delicious touch to your everyday meals.', 'Fresh and aromatic dill leaves, perfect for adding a unique flavour to curries, soups, salads, and traditional dishes.', 'products/dill-leaves-img.jpeg', 'dill-leaves', false, 'MG0022', 'active', '2026-08-20 07:38:13.60771+00', '2026-08-20 08:55:23.562791+00', 2);
INSERT INTO public.products_product VALUES (36, 'Gongura Leaves', 'Our fresh Gongura leaves are carefully selected for their natural freshness and distinctive tangy flavour. Also known as sorrel leaves, they are commonly used in South Indian cuisine to prepare Gongura chutney, pickles, curries, dals, and other traditional dishes. A flavourful leafy ingredient that adds a delicious tangy taste to your everyday meals.', 'Fresh and tangy Gongura leaves, perfect for preparing traditional curries, chutneys, pickles, and flavourful Indian dishes.', 'products/gongura-leaves-img.jpeg', 'gongura-leaves', false, 'MG0024', 'active', '2026-08-20 08:58:21.648436+00', '2026-08-20 08:58:21.648448+00', 2);
INSERT INTO public.products_product VALUES (37, 'Ivy Guard', 'Our fresh ivy gourd is carefully selected for its tenderness, quality, and natural freshness. Also known as Tindora or Kovakkai, it is commonly used in curries, poriyal, stir-fries, sambar, and other Indian dishes. A versatile and flavourful vegetable that makes a delicious addition to your everyday meals.', 'Fresh and tender ivy gourd, perfect for curries, poriyal, stir-fries, and a variety of traditional Indian dishes.', 'products/ivy-guard-img.jpeg', 'ivy-guard', false, 'MG0025', 'active', '2026-08-20 08:59:54.587523+00', '2026-08-20 08:59:54.587536+00', 1);
INSERT INTO public.products_product VALUES (38, 'Knol Khol', 'Our fresh Knol Khol is carefully selected for its crisp texture, mild flavour, and natural freshness. Also known as Kohlrabi, it can be used in curries, kootu, poriyal, stir-fries, soups, and a variety of Indian dishes. A versatile and delicious vegetable that makes a healthy addition to your everyday meals.', 'Fresh and tender Knol Khol, perfect for curries, kootu, poriyal, soups, and healthy everyday meals.', 'products/knol-khol-img.jpeg', 'knol-khol', false, 'MG0026', 'active', '2026-08-20 09:02:55.704157+00', '2026-08-20 09:02:55.70417+00', 1);
INSERT INTO public.products_product VALUES (39, 'Lemon', 'Our fresh lemons are carefully selected for their quality, juiciness, and natural tangy taste. They can be used to prepare fresh juices, lemonade, salads, marinades, chutneys, and a variety of Indian dishes. A versatile and refreshing fruit that adds a burst of flavour to your everyday meals.', 'Fresh and juicy lemons with a natural tangy flavour, perfect for juices, cooking, salads, and refreshing drinks.', 'products/lemon-img.jpeg', 'lemon', false, 'MG0027', 'active', '2026-08-20 09:04:35.144149+00', '2026-08-20 09:04:35.144161+00', 1);
INSERT INTO public.products_product VALUES (40, 'Maa Ginger', 'Our fresh Maa Ginger is carefully selected for its quality, freshness, and distinctive flavour. Commonly used in South Indian cooking, it can be added to curries, chutneys, pickles, rice dishes, and other traditional recipes. A flavourful ingredient that adds a fresh and aromatic touch to your everyday meals.', 'Fresh Maa Ginger with a unique aroma and natural flavour, perfect for curries, chutneys, pickles, and traditional Indian dishes.', 'products/maa-ginger-img.jpeg', 'maa-ginger', false, 'MG0028', 'active', '2026-08-20 09:16:24.293668+00', '2026-08-20 09:16:24.29368+00', 1);
INSERT INTO public.products_product VALUES (41, 'Meethi Leaves', 'Our fresh Meethi Leaves, also known as fenugreek leaves, are carefully selected for their freshness, natural aroma, and distinctive flavour. They can be used in curries, dals, stir-fries, parathas, and many traditional Indian recipes. A flavourful leafy vegetable that adds a delicious touch to your everyday meals.', 'Fresh and aromatic Meethi Leaves, perfect for curries, dals, parathas, and a variety of healthy Indian dishes.', 'products/meethi-leaves-img.jpeg', 'meethi-leaves', false, 'MG0029', 'active', '2026-08-20 09:18:19.256878+00', '2026-08-20 09:18:19.25689+00', 2);
INSERT INTO public.products_product VALUES (42, 'Moringa Leaves', 'Our fresh Moringa Leaves are carefully selected for their quality, freshness, and natural flavour. Also known as drumstick leaves, they are commonly used in South Indian cooking to prepare soups, curries, dals, poriyal, and other traditional dishes. A versatile leafy ingredient that makes a nutritious and flavourful addition to your everyday meals.', 'Fresh and nutritious Moringa Leaves, perfect for preparing soups, curries, dals, and a variety of healthy dishes.', 'products/moringa-leaves-img.jpeg', 'moringa-leaves', false, 'MG0030', 'active', '2026-08-20 09:20:07.739703+00', '2026-08-20 09:20:07.739715+00', 2);
INSERT INTO public.products_product VALUES (43, 'Palak', 'Our fresh Palak, also known as spinach, is carefully selected for its tender leaves, natural freshness, and mild flavour. It can be used to prepare curries, dals, soups, stir-fries, parathas, smoothies, and many traditional Indian dishes. A versatile leafy vegetable that makes a delicious and nutritious addition to your everyday meals.', 'Fresh and tender Palak leaves, perfect for curries, dals, soups, smoothies, and a variety of healthy dishes.', 'products/palak-img.jpeg', 'palak', false, 'MG0031', 'active', '2026-08-20 09:22:47.944178+00', '2026-08-20 09:22:47.944191+00', 2);
INSERT INTO public.products_product VALUES (44, 'Radish', 'Our fresh radish is carefully selected for its crisp texture, natural freshness, and distinctive flavour. It can be used in salads, sambar, curries, poriyal, parathas, and a variety of traditional Indian dishes. A versatile and delicious vegetable that adds freshness and flavour to your everyday meals.', 'Fresh and crisp radish with a mild, peppery flavour, perfect for salads, curries, sambar, and traditional Indian dishes.', 'products/radish-img.jpeg', 'radish', false, 'MG0032', 'active', '2026-08-20 09:26:53.134064+00', '2026-08-20 09:26:53.134077+00', 1);
