INSERT INTO public.products_product VALUES (46, 'Ridge Guard', 'Our fresh ridge gourd is carefully selected for its tenderness, natural freshness, and mild flavour. It is commonly used in curries, kootu, poriyal, sambar, soups, and other traditional Indian dishes. The peel can also be used to prepare flavourful chutneys. A versatile and delicious vegetable for your everyday meals.', 'Fresh and tender ridge gourd, perfect for curries, kootu, poriyal, chutneys, and a variety of healthy Indian dishes.', 'products/ridge-guard-img.jpeg', 'ridge-guard', false, 'MG0034', 'active', '2026-08-20 09:30:39.872043+00', '2026-08-20 09:30:39.872055+00', 1);
INSERT INTO public.products_product VALUES (47, 'Small Onion', 'Our fresh small onions are carefully selected for their quality, freshness, and rich flavour. Also known as shallots or sambar onions, they are commonly used in sambar, curries, gravies, chutneys, pickles, and a variety of South Indian dishes. A versatile kitchen essential that adds delicious taste and aroma to your everyday cooking.', 'Fresh and flavourful small onions, perfect for curries, sambar, chutneys, gravies, and traditional Indian dishes.', 'products/small-onion-img.jpeg', 'small-onion', false, 'MG0035', 'active', '2026-08-20 09:32:00.574209+00', '2026-08-20 09:32:00.574221+00', 1);
INSERT INTO public.products_product VALUES (48, 'Snake Guard', 'Our fresh snake gourd is carefully selected for its tenderness, natural freshness, and mild flavour. It is commonly used in curries, kootu, poriyal, sambar, soups, and other traditional Indian dishes. A versatile and delicious vegetable that makes a fresh addition to your everyday meals.', 'Fresh and tender snake gourd, perfect for curries, kootu, poriyal, soups, and a variety of traditional Indian dishes.', 'products/snake-guard-img.jpeg', 'snake-guard', false, 'MG0036', 'active', '2026-08-20 09:32:59.736288+00', '2026-08-20 09:32:59.7363+00', 1);
INSERT INTO public.products_product VALUES (49, 'Tomato Country', 'Our fresh country tomatoes are carefully selected for their natural taste, juiciness, and freshness. Known for their rich flavour and aroma, they are ideal for preparing curries, gravies, rasam, sambar, chutneys, salads, and a variety of traditional Indian dishes. A versatile kitchen essential that adds delicious taste and natural freshness to your everyday meals.', 'Fresh and juicy country tomatoes with a natural tangy flavour, perfect for curries, gravies, salads, chutneys, and everyday cooking.', 'products/tomato-country-img.jpeg', 'tomato-country', false, 'MG0037', 'active', '2026-08-20 09:34:41.421562+00', '2026-08-20 09:34:41.421573+00', 1);
INSERT INTO public.products_product VALUES (50, 'Hybrid Tomato', 'Our fresh hybrid tomatoes are carefully selected for their quality, firmness, vibrant colour, and juicy texture. They are ideal for preparing curries, gravies, rasam, sambar, chutneys, salads, sauces, and a variety of Indian dishes. A versatile kitchen essential that adds fresh flavour and richness to your everyday meals.', 'Fresh and juicy hybrid tomatoes, perfect for curries, gravies, salads, chutneys, and everyday cooking.', 'products/tomato-hybrid-img.jpeg', 'hybrid-tomato', false, 'MG0038', 'active', '2026-08-20 09:37:36.535391+00', '2026-08-20 09:37:36.535404+00', 1);
INSERT INTO public.products_product VALUES (51, 'Yam Suran', 'Our fresh Yam Suran is carefully selected for its quality, firm texture, and natural freshness. Also known as elephant foot yam, it can be used to prepare curries, poriyal, fries, chips, cutlets, and many traditional Indian dishes. A versatile and flavourful vegetable that makes a delicious addition to your everyday meals.', 'Fresh and firm Yam Suran, perfect for curries, poriyal, fries, chips, and a variety of traditional Indian dishes.', 'products/yam-suran-img.jpeg', 'yam-suran', false, 'MG0039', 'active', '2026-08-20 09:38:52.622378+00', '2026-08-20 09:38:52.62239+00', 1);
INSERT INTO public.products_product VALUES (19, 'Cabbage', 'Our fresh Cabbage is carefully sourced from trusted farms to ensure superior freshness, crispness, and quality. Its mild flavor and crunchy texture make it ideal for salads, stir-fries, curries, soups, coleslaw, and stuffed dishes. Rich in dietary fiber, vitamins C and K, and antioxidants, cabbage is a nutritious addition to a balanced diet. Enjoy farm-fresh Cabbage delivered to your doorstep for delicious and healthy home cooking.', 'Fresh, crisp Cabbage with tender leaves, perfect for salads, stir-fries, curries, soups, and healthy everyday meals.', 'products/cabbage-img.jpeg', 'cabbage', true, 'MG007', 'active', '2026-08-04 12:21:26.231121+00', '2026-08-21 09:44:24.468359+00', 1);
